import 'package:flutter_bloc/flutter_bloc.dart';import 'package:sehatak/core/services/women_service.dart';import 'package:sehatak/core/models/women/women_models.dart';import 'women_event.dart';import 'women_state.dart';class WomenBloc extends Bloc<WomenEvent,WomenState>{final WomenService service;WomenBloc({WomenService?service}):service=service??WomenService(),super(const WomenState()){on<WomenStarted>(_load);on<WomenRefreshed>(_load);on<WomenFilterBySpecialty>(_filter);on<WomenSearch>(_search);}Future<void>_load(WomenEvent e,Emitter<WomenState>emit)async{emit(state.copyWith(isLoading:true,errorMessage:null));try{final r=await Future.wait([service.getTopDoctors(limit:20),service.streamClinics(limit:20).first,service.streamTips(limit:20).first,service.streamHospitals(limit:10)]);emit(state.copyWith(isLoading:false,doctors:r[0]as List<WomenDoctor>,clinics:r[1]as List<WomenClinic>,tips:r[2]as List<WomenTip>,hospitals:r[3]as List<WomenHospital>));}catch(x){emit(state.copyWith(isLoading:false,errorMessage:x.toString()));}}Future<void>_filter(WomenFilterBySpecialty e,Emitter<WomenState>emit)async{emit(state.copyWith(isLoading:true,selectedSpecialty:e.specialty));try{emit(state.copyWith(isLoading:false,doctors:await service.streamDoctors(specialty:e.specialty).first));}catch(x){emit(state.copyWith(isLoading:false,errorMessage:x.toString()));}}void _search(WomenSearch e,Emitter<WomenState>emit){final q=e.query.toLowerCase();emit(state.copyWith(doctors:state.doctors.where((d)=>d.name.toLowerCase().contains(q)||d.specialty.toLowerCase().contains(q)).toList()));}}
